actions.script:
const out = ec.service.sync().name('ironstone.manufacturing.ShopFloorServices.get#Station').requireNewTransaction(true)
        .parameters({appRoot: 'Manufacturing', facilityId: facilityId || null, mine: mine === 'true' || mine === true}).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    ec.web.sendJsonResponse({failed: true, groups: [], rows: [], messageInfos: [{type: 'danger', message}]}); return }
ec.web.sendJsonResponse(out.station || {groups: [], rows: []})

const out = ec.service.sync().name('ironstone.manufacturing.ShopFloorServices.resolve#OperationScan').requireNewTransaction(true)
        .parameters({scanText: scanText || ''}).call() || {}
const message = ec.message.hasError() ? ec.message.getErrorsString() : null
ec.message.clearErrors()
ec.web.sendJsonResponse({matches: message ? [] : Array.from(out.matches || []), message})

ec.service.sync().name('ironstone.manufacturing.AccessServices.check#Record').requireNewTransaction(true).parameters({appRoot: 'Manufacturing',
    recordType: 'operation', recordId: operationWorkEffortId || '', capability: 'operate'}).call()
let out = {}
if (!ec.message.hasError()) out = ec.service.sync().name('mantle.work.ProductionServices.start#ProductionOperation').requireNewTransaction(true)
        .parameters({operationKey: operationKey || null, operationWorkEffortId: operationWorkEffortId || '',
            confirmSwitch: confirmSwitch === 'true' || confirmSwitch === true}).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    const match = /([A-Z][A-Z0-9]*(_[A-Z0-9]+)+):/.exec(message)
    ec.web.sendJsonResponse({failed: true, reasonCode: match ? match[1] : null,
        message: message.replace(/^(Error: )*[A-Z][A-Z0-9_]*: /, ''), messageInfos: [{type: 'danger', message}]}); return }
const result = out.result || {}
ec.web.sendJsonResponse({result, messageInfos: [{type: 'success', message: (result.resultCode === 'JOINED' ? 'Timer started on '
    : result.resultCode === 'RESUMED' ? 'Resumed ' : 'Started ') + (operationWorkEffortId || '')
    + (result.switched ? '; your other timer was stopped' : '')}]})
